"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["1662"],{24778(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_origens","status":422,"titulo":"A cascata excede o limite de 8 origens"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_origens","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["Os destinos declarados na cascata cobrem mais de 8 c\xf3digos distintos de\\n`modalidadeOrigemCodigo`. O limite \xe9 estrutural, n\xe3o de neg\xf3cio por si s\xf3 \u2014\\nprotege contra um corpo do pedido anormalmente grande, j\xe1 que as origens\\ntipicamente correspondem \xe0s sub-reservas de cota de um \xfanico regime legal\\n(hoje, no m\xe1ximo 8 sob a Lei 12.711/2012).","Conferida sobre a contagem de origens **distintas** \u2014 uma origem com\\nv\xe1rias posi\xe7\xf5es na pr\xf3pria fila (uma por destino) n\xe3o conta mais de uma\\nvez para este limite; o que n\xe3o pode se repetir dentro da mesma origem \xe9 o\\nvalor de `ordem`\\n([`ordem_duplicada_na_origem`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem))\\nou o c\xf3digo do destino\\n([`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado)).","Pode coexistir, na mesma resposta, com\\n[`fallback_obrigatorio`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio),\\ncom\\n[`excede_limite_de_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_destinos)\\ne, quando algum item da lista \xe9 inv\xe1lido, com as causas de item \u2014 ver\\n[`campos_obrigatorios`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios).\\nQuando todos os itens s\xe3o v\xe1lidos, pode coexistir tamb\xe9m com\\n[`ordem_duplicada_na_origem`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem),\\n[`ordem_nao_contigua`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua)\\ne\\n[`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado).\\nNunca coexiste com\\n[`sem_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos)\\n\u2014 exceder um limite exige destinos declarados."],"comoResolver":["Reduza a cascata a no m\xe1ximo 8 origens distintas. Se a inten\xe7\xe3o era cobrir\\nmais sub-reservas, confirme o regime legal do processo \u2014 o limite reflete\\na estrutura hoje conhecida da Lei 12.711/2012, n\xe3o uma escolha arbitr\xe1ria."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);